import { test, expect } from '@playwright/test';

test.describe('Notification Panel', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display notification panel when triggered', async ({ page }) => {
    await page.getByRole('button', { name: 'Show Notification' }).click();
    const notificationPanel = page.getByRole('alert');
    await expect(notificationPanel).toBeVisible();
  });

  test('should slide in from the top', async ({ page }) => {
    await page.getByRole('button', { name: 'Show Notification' }).click();
    const notificationPanel = page.getByRole('alert');
    await expect(notificationPanel).toHaveCSS('transform', /translateY\(0\)/);
  });
});
